head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[footer > P > width]<br/>GridView Footer 영역의 너비를 설정합니다.",
    "validation" : [
        "GridView Footer 영역의 너비를 설정합니다.",
        "속성값은 참고용으로 사용되며 GridView 렌더링 시 Footer 영역의 너비는 Footer Column 으로 결정됩니다.",
        "Footer 영역과 Footer Column 영역은 별도로 정의됩니다.",
        "GridView Footer 영역은 별도의 컴포넌트 객체가 생성되지 않는 구조 엘리먼트이므로 스크립트에서 컴포넌트로 조회할 수 없으며, width 값을 조회하거나 변경할 대상 객체 자체가 존재하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_width.setValue("300px");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 설정
    //  - width 는 footer(Footer 영역) 단위 속성이며 dynamic N 이므로 렌더 시점에만 설정한다.
    //  - Footer Column 영역은 footer_col1 ~ footer_col4 로 별도 정의한다.
    let cWidth = con_width.getValue();
    let lblWidth = (cWidth === '') ? '미설정' : cWidth;
    let attrWidth = (cWidth === '') ? '' : ' width="' + cWidth + '"';

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] GridView 하위에 w2:footer 를 선언하고 Footer 영역에만 width 속성을 설정 (Footer Column 영역은 footer_col1 ~ footer_col4 로 별도 선언)\n[현재] footer width = ' + lblWidth + '\n[절차] 옵션 변경 후 Target 재생성 -> 너비 확인 / Footer 컴포넌트 조회\n[확인] 선언한 width 값, 렌더된 Footer 영역의 실제 너비, Footer Column 폭 합 3 가지를 대비하여 결과창에서 확인"', '', 'label1');

    // dataList 생성 (col1~col4 / 4행)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (footer 포함)
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:600px;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '<w2:footer style="" id="footer1"' + attrWidth + '>';
    strTarget += '<w2:row style="" id="row3">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="footer_col1" value="footer1"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="footer_col2" value="footer2"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="footer_col3" value="footer3"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="footer_col4" value="footer4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 렌더된 Footer 영역(table) 요소 조회
scwin.getFooterArea = function () {
    return target1.render.querySelector("table[id$='_foot_table']");
}



// footer 에 설정한 width 의 실제 반영 여부 확인
scwin.btn_checkWidth_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");

    let cWidth = con_width.getValue();
    let footArea = scwin.getFooterArea();
    let footCols = footArea ? footArea.querySelectorAll("tbody > tr:first-child > td") : [];

    let colWidths = [];
    let colSum = 0;
    for (let i = 0; i < footCols.length; i++) {
        colWidths.push(footCols[i].offsetWidth);
        colSum += footCols[i].offsetWidth;
    }

    let realWidth = footArea ? footArea.offsetWidth : -1;
    let styleWidth = footArea ? parseInt(footArea.style.width, 10) : -1;
    let attrOnRender = footArea ? footArea.getAttribute("width") : null;
    let declaredWidth = (cWidth === '') ? -1 : parseInt(cWidth, 10);

    bottom.setReturnValue("[선언] footer 에 설정한 width : " + (cWidth === '' ? '(미설정)' : cWidth) + " / 렌더된 Footer 영역 요소의 width 속성 : " + (attrOnRender === null ? '(없음)' : attrOnRender));
    bottom.setReturnValue("[렌더] Footer 영역의 실제 너비 : " + (footArea ? realWidth + "px (style.width : " + footArea.style.width + ")" : '(Footer 영역 없음)'));
    bottom.setReturnValue("[합계] Footer Column 폭 합 : " + colSum + "px (" + colWidths.join(" + ") + ") / 선언한 width 로 결정되었는지 : " + (declaredWidth === styleWidth) + " / Footer Column 폭 합으로 결정되었는지 : " + (colSum === styleWidth));
    bottom.setReturnValue("[영역] Footer 영역 요소 : " + (footArea ? footArea.id : '-') + " / Footer Column 영역 요소 : " + (footCols.length > 0 ? footCols[0].id : '-'));
}



// id 로 조회된 결과가 WebSquare 컴포넌트인지 판별
scwin.isComponent = function (obj) {
    return !!(obj && typeof obj.getPluginName === 'function');
}



// 선언한 id / 렌더된 id 로 Footer 영역 컴포넌트 조회 시도
scwin.lookupComponent = function (id) {
    if (!id) {
        return '(id 없음)';
    }

    let obj = WebSquare.util.getComponentById(id);

    if (!obj) {
        obj = WebSquare.util.getComponentById("mf_" + id);
    }

    if (!obj) {
        return 'undefined (조회 결과 없음)';
    }

    if (scwin.isComponent(obj)) {
        return 'WebSquare 컴포넌트 (' + obj.getPluginName() + ')';
    }

    if (obj.nodeType === 1) {
        return obj.nodeName + ' DOM 엘리먼트 (컴포넌트 객체 아님)';
    }

    return String(obj);
}



// Footer 영역이 컴포넌트 객체로 조회되는지, width 조회/변경 대상 객체가 존재하는지 확인
scwin.btn_checkFooterObject_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");

    let footArea = scwin.getFooterArea();
    let renderedId = footArea ? footArea.id : '';

    let candidates = [
        WebSquare.util.getComponentById("footer1"),
        WebSquare.util.getComponentById("mf_footer1"),
        renderedId ? WebSquare.util.getComponentById(renderedId) : null
    ];

    let footComp = null;
    for (let i = 0; i < candidates.length; i++) {
        if (scwin.isComponent(candidates[i])) {
            footComp = candidates[i];
            break;
        }
    }

    bottom.setReturnValue("[조회] 선언한 footer id (footer1) 로 컴포넌트 조회 : " + scwin.lookupComponent("footer1"));
    bottom.setReturnValue("[조회] 렌더된 Footer 영역 id (" + (renderedId === '' ? '-' : renderedId) + ") 로 컴포넌트 조회 : " + scwin.lookupComponent(renderedId));
    bottom.setReturnValue("[대상] width 를 조회/변경할 Footer 컴포넌트 객체 존재 여부 : " + (footComp !== null));
}
